
targets = [
    0x92, 0xe8, 0xf1, 0xc5,
    0x9b, 0xeb, 0xd1, 0x90,
    0xff, 0xe7, 0xa1, 0xa1,
    0x99, 0xb7, 0xea, 0xfa,
    0xcc, 0xbb, 0xee, 0x104,
    0x116, 0xed, 0xf9, 0xde,
    0x11a, 0x111, 0xc1, 0xe6,
    0xf5, 0xd7, 0xca, 0xc1,
    0xe3
]

key = [0xde, 0xad, 0xbe, 0xef]

flag = []
for i in range(len(targets)):
    
    val = targets[i] - (2 * i)
    char_code = val ^ key[i % 4]
    flag.append(chr(char_code))

print("".join(flag))
